import unittest

from hourglass.models import Span
from hourglass.rounding import round_span, rounded_labels


class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest(self):
        span = Span(9 * 60 + 7, 17 * 60 + 8)
        self.assertEqual(
            round_span(span, 15), Span(540, 1020)
        )

    def test_halves_round_up(self):
        self.assertEqual(
            round_span(Span(67, 127), 15), Span(60, 120)
        )
        self.assertEqual(
            round_span(Span(68, 128), 15), Span(75, 135)
        )

    def test_end_of_day_is_kept(self):
        self.assertEqual(
            round_span(Span(1000, 1440), 30), Span(990, 1440)
        )

    def test_vanishing_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 543), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(540, 1035), Span(601, 662)]
        self.assertEqual(
            rounded_labels(spans, 15),
            ["09:00-17:15 (8h 15m)", "10:00-11:00 (1h 00m)"]
        )

    def test_empty(self):
        self.assertEqual(rounded_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                rounded_labels([Span(0, 60)], step)

    def test_bad_step_raises_without_spans(self):
        with self.assertRaises(ValueError):
            rounded_labels([], 0)


if __name__ == "__main__":
    unittest.main()
